def classify_archetype(combined: str, mr: List[str], ma: List[str], mcs: List[str], non_tech: List[str]) -> str: return 'Noise / Promo' if _match_terms(combined, SPAM_TERMS) else ('Out of Scope (Non-AI/Robotics)' if ((not mr and not ma) or (non_tech and (len(mr) + len(ma) <= 1) and not mcs)) else ('Embodied AI & Robotics' if mr else ('SLMs & Fine-Tuning' if _match_terms(combined, ['slm', 'small language models', 'distillation', 'knowledge distillation', 'qlora', 'lora', 'post-training']) else ('Computer Vision & VLM' if _match_terms(combined, ['computer vision', 'jepa', 'yolo', 'object detection', 'smolvlm', 'ocr', 'segmentation']) else ('AI Infra & GPU Systems' if _match_terms(combined, ['vllm', 'sglang', 'triton', 'kv-cache', 'cuda', 'flashattention', 'mamba', 'serving']) else ('Agentic AI & RAG' if _match_terms(combined, ['agent', 'multi-agent', 'rag', 'langchain', 'langgraph', 'llamaindex', 'crewai']) else ('Founder / Spinout Builder' if _match_terms(combined, ['founder', 'co-founder', 'ceo']) else 'AI & ML Researcher')))))))

def evaluate_candidate_fit(candidate: Dict[str, Any], query_segment: str) -> Dict[str, Any]: uname = config . extract_x_handle(candidate . get('username', '')); bio_l = (candidate . get('bio') or '') . lower(); loc_l = (candidate . get('location') or '') . lower(); posts = candidate . get('recent_posts') or []; posts_txt = ' ' . join(p . get('text', '') for p in posts) . lower(); tags_txt = ' ' . join(candidate . get('segment_tags') or []) . lower(); combined = f'{bio_l} {loc_l} {posts_txt}' . strip(); combined_full = f'{combined} {tags_txt} {uname . lower()}' . strip(); best_post = posts[0] if posts else {'text': candidate . get('bio', ''), 'url': f'{config . X_WEB}/{uname}'}; ev_quote = best_post . get('text', '') or candidate . get('bio', '') or f'Profile @{uname} on X (No AI/Robotics bio or posts found)'; ev_url = best_post . get('url', f'{config . X_WEB}/{uname}'); spam_hits = _match_terms(combined, SPAM_TERMS); mr = _match_terms(combined_full, ROBOTICS_TERMS); ma = _match_terms(combined_full, AI_TERMS); mcs = _match_terms(combined_full, CS_CONTEXT_TERMS); non_tech = _match_terms(combined, NON_TECH_TERMS); msea = _match_terms(combined_full, SEA_TERMS); mh = _match_terms(combined_full, HOOK_TERMS); q_terms = _extract_query_terms(query_segment); is_broad = _is_broad_default_query(query_segment, q_terms); q_hits = _match_terms(combined_full, q_terms); base_arch = classify_archetype(combined_full, mr, ma, mcs, non_tech); is_out = (not mr and not ma) or (bool(non_tech) and (len(mr) + len(ma) <= 1) and not mcs); is_weak = (not is_out) and ((len(mr) + len(ma) == 1) and not mcs); is_seg_mismatch = (not is_out) and (not is_weak) and (not spam_hits) and (not is_broad) and (len(q_terms) > 0) and (len(q_hits) == 0); archetype = (f'Filtered (Not in "{query_segment[:22] . strip()}")' if is_seg_mismatch else base_arch); tech = 0 if (spam_hits or is_out) else (10 if is_weak else (16 if is_seg_mismatch else min(35, 14 + 5 * len(mr) + 4 * len(ma) + 4 * len(q_hits) + 2 * min(3, len(mcs))))); sea = 0 if (spam_hits or is_out) else (6 if is_weak else (8 if is_seg_mismatch else (25 if len(msea) >= 2 else (21 if len(msea) == 1 else (16 if (len(mr) + len(ma) >= 2 or len(q_hits) >= 2) else 10))))); readiness = 0 if spam_hits else (4 if is_out else (6 if is_weak else (8 if is_seg_mismatch else (min(25, 11 + 4 * len(mh) + 2 * min(3, len(q_hits))) if mh else 10)))); has_quant = bool(re . search(r'\b(\d+([_]\d+)?(ms|x|%|gb|tb|dof|ha|hrs|hours|b|\$))\b', combined)); snr = 5 if spam_hits else (4 if (is_out and non_tech) else (8 if is_out else (6 if is_weak else (6 if is_seg_mismatch else min(15, 9 + (2 if has_quant else 0) + min(4, len(q_hits))))))); total = min(99, tech + sea + readiness + snr); r_list = (['Excluded (Noise Filter): Promotional token/airdrop pattern detected'] if spam_hits else ([f'Excluded (Out of Domain): Non-AI/Robotics profile ({", " . join(non_tech[:3])}) with zero AI/Robotics engineering signals' if non_tech else 'Excluded (Out of Domain): No verifiable AI, Machine Learning, or Robotics signals found in profile bio or recent posts'] if is_out else ([f'Insufficient Technical Depth: Only isolated mention ({(mr + ma)[0]}) without engineering or research context'] if is_weak else ([f'Segment Filter: Profile is in {base_arch} but does not match your custom search field ("{query_segment[:36] . strip()}")'] if is_seg_mismatch else ([f'Matched search field ({", " . join(q_hits[:5])})'] if q_hits else []) + ([f'Embodied AI / Robotics depth ({", " . join(mr[:4])})'] if mr else []) + ([f'AI / ML / Systems depth ({", " . join(ma[:4])})'] if ma else []) + ([f'Southeast Asia ecosystem footprint ({candidate . get("location") or ", " . join(msea[:2])})'] if msea else ['Global AI & Robotics ecosystem leader']) + ([f'Active builder / research hook ({", " . join(mh[:3])})'] if mh else []))))); return {'fit_score': total, 'role_archetype': archetype, 'matches_segment': not is_seg_mismatch and not is_out and not is_weak and not spam_hits, 'matched_query_terms': q_hits[:6], 'score_breakdown': {'technical_depth': tech, 'sea_ecosystem_fit': sea, 'conversation_readiness': readiness, 'signal_to_noise': snr}, 'fit_reasons': r_list, 'evidence_quote': ev_quote, 'evidence_url': ev_url}

def verify_dm_grounding(draft_dm: str, candidate: Dict[str, Any]) -> Dict[str, Any]: text = (draft_dm or '') . strip(); lower_dm = text . lower(); ev_txt = f"{candidate . get('bio', '')} {candidate . get('evidence_quote', '')} {candidate . get('username', '')}" . lower(); ev_tokens = {tok for tok in re . findall(r'[a-z0-9_-]{3,}', ev_txt) if tok not in {'just', 'with', 'from', 'that', 'this', 'have', 'looking', 'building', 'open', 'across', 'the', 'and', 'for', 'our'}}; matched = [tok for tok in ev_tokens if tok in lower_dm]; is_filtered_dm = text . startswith('[Out of Scope') or text . startswith('[Filtered'); has_anchor = len(matched) >= 1 and not is_filtered_dm; cliches = [c for c in config . BANNED_CLICHES if c in lower_dm]; no_cliche = len(cliches) == 0; has_q = '?' in text; len_ok = 50 <= len(text) <= 480; no_links = not bool(re . search(config . SCHEME + '?' + ':' + '//', text)); checks = [{'rule': 'Evidence Anchor', 'passed': has_anchor, 'detail': f'Matched tokens: {", " . join(matched[:4])}'}, {'rule': 'Zero Invented Familiarity', 'passed': no_cliche, 'detail': 'No fake flattery cliches'}, {'rule': 'Conversational Question Hook', 'passed': has_q, 'detail': 'Ends with question (?)'}, {'rule': 'Optimal DM Length (50-480 chars)', 'passed': len_ok, 'detail': f'{len(text)} chars'}, {'rule': 'Link-Free Cold DM Policy', 'passed': no_links, 'detail': 'No URLs in cold DM'}]; passed = sum(1 for c in checks if c['passed']); return {'all_passed': (passed == len(checks)) and not is_filtered_dm, 'score_label': 'Filtered / Out of Scope' if is_filtered_dm else f'{passed}/{len(checks)} Checks Passed', 'matched_anchors': matched[:5], 'checks': [] if is_filtered_dm else checks}

def generate_grounded_dm(candidate: Dict[str, Any], gemini_key: str = '', sender_context: str = 'GenAI Fund') -> str: uname = config . extract_x_handle(candidate . get('username', '')); fit_score = int(candidate . get('fit_score', 0)); raw_name = candidate . get('display_name', '') or uname or 'there'; first_name = raw_name . split('|')[0] . replace(f'Dr{config . D}', '') . strip() . split()[0] if raw_name else 'there'; ev_quote = (candidate . get('evidence_quote') or candidate . get('bio') or '') . strip(); short_ev = (ev_quote[:110] + '...') if len(ev_quote) > 110 else (ev_quote or f'your AI & robotics work on @{uname}'); return f'[Out of Scope / Segment Filtered — Fit Score {fit_score}/100] @{uname} does not match the active target field or AI/Robotics threshold.' if fit_score < 50 else f"Hi {first_name} — came across your work on @{uname} ('{short_ev}'). At GenAI Fund we partner with technical AI and robotics builders on enterprise pilots and ecosystem growth across Southeast Asia and globally. What technical milestones or deployment bottlenecks are you focusing on next?"

def classify_reply_intent(reply_text: str) -> Dict[str, Any]: low = (reply_text or '') . lower(); is_opt = any(k in low for k in ['unsubscribe', 'not interested', 'stop', 'remove me']); is_warm = ('?' in (reply_text or '')) or any(k in low for k in ['call', 'chat', 'pilot', 'deck', 'next week', 'tuesday', 'thursday', 'sure', 'interested', 'coffee', 'zoom', 'meet', 'yes']); return {'reply_intent': 'opt_out', 'prospect_status': 'blocked', 'needs_attention': 0, 'attention_reason': 'Opt-out requested — moved to Blocked'} if is_opt else ({'reply_intent': 'warm_interest_or_question', 'prospect_status': 'needs_attention', 'needs_attention': 1, 'attention_reason': 'High-Priority Warm Reply — Ready for FDE Partner takeover'} if is_warm else {'reply_intent': 'general_reply', 'prospect_status': 'replied', 'needs_attention': 1, 'attention_reason': 'Inbound reply received — review thread'})
